import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.platform.InMemoryTransactionManager;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderConfirmationTest {

    /** Stands in for the carrier and records whether a transaction was open when it was called. */
    static class RecordingCarrier implements CarrierGateway {

        boolean failNextBooking;
        boolean transactionOpenDuringBooking;
        int bookings;

        @Override
        public String book(String orderId) {
            bookings++;
            transactionOpenDuringBooking = InMemoryTransactionManager.isOpen();
            if (failNextBooking) {
                failNextBooking = false;
                throw new IllegalStateException("carrier unavailable");
            }
            return "TRK-" + orderId;
        }
    }

    @Test
    void confirmingBooksAShipmentAndStoresItsTrackingNumber() {
        RecordingCarrier carrier = new RecordingCarrier();
        try (var shop = shopWith(carrier)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            assertNull(orders.summary(id).trackingNumber());

            orders.confirm(id);

            assertEquals(1, carrier.bookings);
            assertFalse(carrier.transactionOpenDuringBooking, "the carrier must be called outside a transaction");
            var summary = orders.summary(id);
            assertEquals("CONFIRMED", summary.status());
            assertEquals("TRK-" + id, summary.trackingNumber());
        }
    }

    @Test
    void aFailedBookingLeavesTheOrderPlacedAndConfirmableAgain() {
        RecordingCarrier carrier = new RecordingCarrier();
        try (var shop = shopWith(carrier)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            carrier.failNextBooking = true;
            assertThrows(IllegalStateException.class, () -> orders.confirm(id));

            var failed = orders.summary(id);
            assertEquals("PLACED", failed.status());
            assertNull(failed.trackingNumber());

            orders.confirm(id);

            var confirmed = orders.summary(id);
            assertEquals("CONFIRMED", confirmed.status());
            assertTrue(confirmed.trackingNumber().startsWith("TRK-"));
        }
    }

    private static AnnotationConfigApplicationContext shopWith(CarrierGateway carrier) {
        var shop = new AnnotationConfigApplicationContext();
        shop.register(ShopConfig.class);
        shop.registerBean(CarrierGateway.class, () -> carrier, definition -> definition.setPrimary(true));
        shop.refresh();
        return shop;
    }
}
